/**
 * 内部方法：发送一对一聊天通用数据.
 *
 * @param userProcessor
 * @param from_user_id
 * @param to_user_id
 * @param dataContent
 * @param typeu 应用层专用字段——用于应用层存放聊天、推送等场景下的消息类型。注意：此值为-1时表示未定义。
 *              MobileIMSDK_X框架中，本字段为保留字段，不参与框架的核心算法，专留用应用层自行定义和使用。
 * @param fnProcessOfflineMessage 非必须参数，用于消息没有在线发送成功时的离线消息处理回调
 * @returns {boolean}
 */
function sendData4(userProcessor, from_user_id, to_user_id, dataContent, QoS, fingerPrint, typu, fnProcessOfflineMessage) {
    //return sendData3(userProcessor, from_user_id, to_user_id, dataContent, fnProcessOfflineMessage);
    return sendData2(userProcessor
        , ProtocalFactory.createCommonData(dataContent, from_user_id, to_user_id, QoS, fingerPrint, typu), fnProcessOfflineMessage);
}

